import sys
def main():
    d = sys.stdin.buffer.read().split()
    n, q = int(d[0]), int(d[1])
    par = list(range(n + 1)); pot = [0] * (n + 1); sz = [1] * (n + 1)
    def find(x):
        path = []
        while par[x] != x:
            path.append(x); x = par[x]
        for v in reversed(path):
            p = par[v]
            if p != x:
                pot[v] += pot[p]; par[v] = x
        return x
    MOD = 10**9 + 7
    contra = 0; unknown = 0; s = 0; qi = 0; k = 2
    for _ in range(q):
        if d[k] == b'1':
            x = int(d[k + 1]); y = int(d[k + 2]); w = int(d[k + 3]); k += 4
            rx = find(x); ry = find(y)
            if rx == ry:
                if pot[y] - pot[x] != w: contra += 1
            else:
                dlt = w + pot[x] - pot[y]
                if sz[rx] < sz[ry]:
                    par[rx] = ry; pot[rx] = -dlt; sz[ry] += sz[rx]
                else:
                    par[ry] = rx; pot[ry] = dlt; sz[rx] += sz[ry]
        else:
            x = int(d[k + 1]); y = int(d[k + 2]); k += 3
            qi += 1
            if find(x) == find(y):
                s = (s + qi * (pot[y] - pot[x])) % MOD
            else:
                unknown += 1
    print(contra, unknown, s)
main()

import sys
from bisect import bisect_left, bisect_right
def main():
    d = sys.stdin.buffer.read().split()
    n = int(d[0]); p = 1
    rects = []
    for _ in range(n):
        rects.append((int(d[p]), int(d[p + 1]), int(d[p + 2]), int(d[p + 3]))); p += 4
    q = int(d[p]); p += 1
    PX = [0] * q; PY = [0] * q
    for i in range(q):
        PX[i] = int(d[p]); PY[i] = int(d[p + 1]); p += 2
    ys = sorted(set(PY))
    D = len(ys)
    ev = []
    for x1, y1, x2, y2 in rects:
        lo = bisect_left(ys, y1) + 1; hi = bisect_right(ys, y2)
        if lo <= hi:
            ev.append((x1, 0, lo, hi, 1)); ev.append((x2 + 1, 0, lo, hi, -1))
    for i in range(q):
        ev.append((PX[i], 1, i, 0, 0))
    ev.sort()
    B = [0] * (D + 2)
    yi = {y: i + 1 for i, y in enumerate(ys)}
    ans = [0] * q
    for x, typ, a, b, v in ev:
        if typ == 0:
            i = a
            while i <= D:
                B[i] += v; i += i & -i
            i = b + 1
            while i <= D:
                B[i] -= v; i += i & -i
        else:
            s = 0; i = yi[PY[a]]
            while i > 0:
                s += B[i]; i -= i & -i
            ans[a] = s
    MOD = 10**9 + 7
    print(sum((i + 1) * c for i, c in enumerate(ans)) % MOD)
main()
